def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timezone, timedelta

    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    seconds = nanoseconds // 1_000_000_000
    nanos = nanoseconds % 1_000_000_000

    if tz is None:
        # Assuming LocalTime if no timezone is provided
        dt = datetime.fromtimestamp(seconds).replace(microsecond=0)
        dt += timedelta(microseconds=nanos // 1000)
        return dt.time().replace(microsecond=nanos // 1000)
    else:
        if not isinstance(tz, (timezone, str)):
            raise ValueError("tz must be a datetime.timezone or a string")
        if isinstance(tz, str):
            try:
                tz = timezone(timedelta(hours=int(tz)))
            except ValueError:
                raise ValueError("tz string must be in the format '+/-HH'")

        dt = datetime.fromtimestamp(seconds, tz).replace(microsecond=0)
        dt += timedelta(microseconds=nanos // 1000)
        return dt.time().replace(microsecond=nanos // 1000)

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    from datetime import datetime, timezone, timedelta

    try:
        # Convert nanoseconds to seconds and remaining nanoseconds
        seconds = nanoseconds // 1_000_000_000
        nanosecond_remainder = nanoseconds % 1_000_000_000

        # Create a datetime object in UTC
        time_obj = datetime.min + timedelta(seconds=seconds, microseconds=nanosecond_remainder // 1000)

        # If a timezone is provided, localize the time
        if tz is not None:
            if isinstance(tz, str):
                try:
                    tz = timezone(timedelta(hours=int(tz)))
                except ValueError:
                    raise ValueError("Timezone must be a valid string representation of a timezone offset.")
            elif not isinstance(tz, timezone):
                raise TypeError("Timezone must be a datetime.timezone object.")
            time_obj = time_obj.replace(tzinfo=timezone.utc).astimezone(tz)

        return time_obj.time()

    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

