def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    from itertools import islice
    from concurrent.futures import ThreadPoolExecutor, as_completed

    def run_command(command):
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, check=False)
        return result.returncode, result.stdout

    def chunked_iterable(iterable, size):
        it = iter(iterable)
        while True:
            chunk = list(islice(it, size))
            if not chunk:
                break
            yield chunk

    if not cmd:
        raise ValueError("Command cannot be empty")

    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1")

    command_chunks = chunked_iterable(varargs, _max_length // len(' '.join(cmd)))
    all_commands = [(' '.join(cmd) + ' ' + ' '.join(args)).split() for args in command_chunks]

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_command = {executor.submit(run_command, command): command for command in all_commands}
        results = []
        for future in as_completed(future_to_command):
            try:
                exit_code, output = future.result()
                results.append((exit_code, output))
            except Exception as e:
                return 1, str(e).encode()

    if all(code == 0 for code, _ in results):
        return 0, b'\n'.join(output for _, output in results)
    else:
        return 1, b'\n'.join(output for _, output in results)

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    from subprocess import Popen, PIPE, STDOUT
    from itertools import islice
    import os

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    processes = []
    results = []
    exit_code = 0

    def run_command(args):
        nonlocal exit_code
        try:
            if color and os.name == 'posix':
                p = Popen(['script', '-q', '/dev/null'] + list(cmd) + args, stdout=PIPE, stderr=STDOUT, text=False)
            else:
                p = Popen(list(cmd) + args, stdout=PIPE, stderr=STDOUT, text=False)
            stdout, stderr = p.communicate()
            if p.returncode != 0:
                exit_code = p.returncode
            return stdout
        except Exception as e:
            exit_code = 1
            return str(e).encode()

    for _ in range(target_concurrency):
        batch = list(islice(varargs, _max_length // len(cmd)))
        if not batch:
            break
        processes.append(run_command(batch))

    for output in processes:
        results.append(output)

    final_output = b''.join(results)
    return exit_code, final_output

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor
    import tempfile

    if not cmd:
        raise ValueError("Command tuple 'cmd' must not be empty.")
    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1.")
    if _max_length <= 0:
        raise ValueError("Maximum command length must be greater than 0.")

    def run_command(command: list[str]) -> subprocess.CompletedProcess:
        kwargs.setdefault('stdout', subprocess.PIPE)
        kwargs.setdefault('stderr', subprocess.PIPE)
        if color and os.name == 'posix':
            kwargs.setdefault('stdout', subprocess.PIPE)
            kwargs.setdefault('stderr', subprocess.PIPE)
            kwargs['universal_newlines'] = True
            return subprocess.run(['script', '-q', '/dev/null'] + command, **kwargs)
        else:
            return subprocess.run(command, **kwargs)

    commands = []
    current_command = list(cmd)
    current_command_length = sum(len(arg) + 1 for arg in current_command)

    for arg in varargs:
        arg_length = len(arg) + 1
        if current_command_length + arg_length > _max_length:
            commands.append(current_command)
            current_command = list(cmd)
