def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    from functools import lru_cache, wraps
    import time

    def decorator(func):
        cache = lru_cache(maxsize=maxsize, typed=typed)

        @wraps(func)
        def wrapper(*args, **kwargs):
            def _make_key(args, kwargs, typed):
                key = args
                if kwargs:
                    key += (typed,) if typed else ()
                    for item in kwargs.items():
                        key += item
                return key

            key = _make_key(args, kwargs, typed)
            cache_time = cache.cache_get(key, default=None)
            current_time = timer()

            if cache_time is not None and current_time - cache_time[0] <= ttl:
                return cache_time[1]

            result = func(*args, **kwargs)
            cache.cache_set(key, (current_time, result))
            return result

        return wrapper

    return decorator

