def _legacy_mergeOrderings(orderings):
    try:
        merged = []
        orderings_dict = {item: set() for sublist in orderings for item in sublist}
        for ordering in orderings:
            for i, item in enumerate(ordering[:-1], start=1):
                orderings_dict[item].update(ordering[i:])

        while orderings_dict:
            # Find items with no preceding items
            heads = [item for item, pre in orderings_dict.items() if not pre]
            if not heads:
                raise ValueError("Circular dependency detected in orderings")
            for head in heads:
                merged.append(head)
                del orderings_dict[head]
                for items in orderings_dict.values():
