        return []

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    # Create a graph where each node points to its successors
    graph = {}
    # Keep track of the last occurrence of each item
    last_occurrence = {}

    for ordering in orderings:
        for i in range(len(ordering)):
            item = ordering[i]
            if i < len(ordering) - 1:
                if item not in graph:
                    graph[item] = set()
                graph[item].add(ordering[i + 1])
            last_occurrence[item] = ordering[i]

    # Perform a topological sort using Kahn's algorithm
    in_degree = {node: 0 for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    queue = [node for node in in_degree if in_degree[node] == 0]
    merged_ordering = []

    while queue:
        if len(queue) > 1:
            # If there are multiple nodes with zero in-degree, we need to ensure
            # that the order respects the last_occurrence constraint
            queue.sort(key=lambda x: last_occurrence.get(x, float('-inf')), reverse=True)
        node = queue.pop(0)
        merged_ordering.append(node)
        if node in graph:
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

    # Check for cycles
    if len(merged_ordering) != len(last_occurrence):
        raise ValueError("The orderings contain cycles or are not properly constrained")

    return merged_ordering

