def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(sql, (str, bytes)):
            if isinstance(params, (dict,)):
                # Assuming named parameters
                out_params = {f':{k}': v for k, v in params.items()}
                out_sql = sql
                for old_param in params.keys():
                    out_sql = out_sql.replace(f':{old_param}', f'%({old_param})s')
                return out_sql, out_params
            elif isinstance(params, (list, tuple)):
                # Assuming ordinal parameters
                out_params = [f'%s'] * len(params)
                return sql, out_params
            else:
                raise ValueError("params must be a dict or a sequence")
        else:
            raise ValueError("sql must be a str or bytes")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(params, dict):
            # Assuming out-style is using ordinal parameters
            placeholders = {key: f":{i+1}" for i, key in enumerate(params)}
            out_params = list(params.values())
            formatted_sql = sql
            for key, placeholder in placeholders.items():
                formatted_sql = formatted_sql.replace(f"%({key})s", placeholder)
        elif isinstance(params, Sequence):
            # Assuming out-style is using named parameters
            placeholders = {f":{i+1}": f":{i+1}" for i in range(len(params))}
            out_params = list(params)
            formatted_sql = sql
            for i, placeholder in enumerate(placeholders.values()):
                formatted_sql = formatted_sql.replace(f"%s", placeholder, 1)
        else:
            raise ValueError("Params must be a dictionary or a sequence.")
        return formatted_sql, out_params
    except Exception as e:
        raise Exception(f"Error formatting SQL query: {e}")

