) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(params, dict):
            # Assuming named style input parameters
            out_style_params = {f":{key}": value for key, value in params.items()}
            for key in out_style_params:
                sql = sql.replace(f"%({key.split(':')[1]})s", key)
        elif isinstance(params, Sequence) and not isinstance(params, str):
            # Assuming positional style input parameters
            out_style_params = [f":{i}" for i in range(len(params))]
            sql_parts = sql.split('%s')
            if len(sql_parts) - 1 != len(params):
