def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    try:
        if not isinstance(xmls, list) or not isinstance(files, list):
            raise ValueError("Both xmls and files must be lists.")

        grouped_files = {os.path.basename(xml).rsplit('.', 1)[0]: [] for xml in xmls}

        for file in files:
            base_name, _ = os.path.splitext(os.path.basename(file))
            for xml_base_name in grouped_files:
                if base_name.startswith(xml_base_name):
                    grouped_files[xml_base_name].append(file)

        return grouped_files

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

