def _explore_folder(folder):
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not os.path.isdir(folder):
        raise ValueError("The provided folder path is not a valid directory.")

    package_data = defaultdict(list)

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    base_name = os.path.splitext(file)[0]
                    package_data[base_name].append({
                        'file_path': file_path,
                        'root_element': root_element.tag,
                        'namespace': root_element.nsmap.get(None) if root_element.nsmap else None
                    })
                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}, skipping.")
                except Exception as e:
                    print(f"Warning: An error occurred while processing file {file_path}: {e}")

    return dict(package_data)

