def pretty(self, indent=0, debug=False):
    try:
        indent_str = '  ' * indent
        if debug:
            return f"{indent_str}<DEBUG> {self.__class__.__name__}: {self.__dict__}"
        else:
            return f"{indent_str}{self.__class__.__name__}: {self.__dict__}"
    except Exception as e:
        return f"{indent_str}<ERROR> Failed to pretty print: {str(e)}"

def pretty(self, indent=0, debug=False):
    try:
        indent_str = '  ' * indent
        output = f"{indent_str}<{self.__class__.__name__}>"
        if debug:
            output += f" {vars(self)}"
        return output
    except Exception as e:
        return f"{indent_str}Error formatting object: {str(e)}"

def pretty(self, indent=0, debug=False):
    try:
        indent_str = '  ' * indent
        result = f"{indent_str}{self.__class__.__name__}(\n"
        for key, value in self.__dict__.items():
            if isinstance(value, (list, tuple, set, dict)):
                value_str = f"[...]" if not debug else str(value).replace('\n', f'\n{indent_str}  ')
            else:
                value_str = str(value)
            result += f"{indent_str}  {key}={value_str},\n"
        result += f"{indent_str})\n"
        return result
    except Exception as e:
        return f"Error pretty printing {self}: {str(e)}"

