    try:
        indent_str = ' ' * (indent * 4)
        if debug:
            representation = f"{indent_str}<Object: {self.__class__.__name__}>\n"
            for attr, value in self.__dict__.items():
                if isinstance(value, str):
                    representation += f"{indent_str}  {attr}: '{value}'\n"
                elif hasattr(value, 'pretty'):
                    representation += f"{indent_str}  {attr}: {value.pretty(indent + 1, debug)}\n"
                else:
                    representation += f"{indent_str}  {attr}: {value}\n"
            return representation
        else:
            return f"{indent_str}{self}\n"
    except Exception as e:
        return f"{indent_str}Error pretty printing object: {e}\n"

