def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path
    import os

    try:
        # Ensure tmp_path is a Path object
        if isinstance(tmp_path, str):
            tmp_path = Path(tmp_path)
        else:
            tmp_path = Path(tmp_path)

        # Create the temporary directory if it doesn't exist
        if not tmp_path.exists():
            tmp_path.mkdir(parents=True, exist_ok=True)

        # Determine the command to decompress the archive
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            command = ['tar', '-xzf', archive_path, '-C', str(tmp_path)]
        elif archive_path.endswith('.tar.bz2'):
            command = ['tar', '-xjf', archive_path, '-C', str(tmp_path)]
        elif archive_path.endswith('.zip'):
            command = ['unzip', archive_path, '-d', str(tmp_path)]
        else:
            raise ValueError("Unsupported archive format")

        # Execute the decompression command
        subprocess.run(command, check=True)

        # Determine the path to the repository
        if filename:
            repo_path = tmp_path / filename
        else:
            # List the contents of the tmp_path and assume the repo is the only directory
            contents = [item for item in tmp_path.iterdir() if item.is_dir()]
            if len(contents) != 1:
                raise ValueError("Could not determine the repository directory")
            repo_path = contents[0]

        # Return the file URL of the repository
        return f"file://{repo_path}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to decompress the archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import subprocess
    from pathlib import Path

    if not isinstance(tmp_path, Path):
        tmp_path = Path(tmp_path)

    try:
        # Ensure the temporary directory exists
        tmp_path.mkdir(parents=True, exist_ok=True)

        # Define the output directory inside the temporary path
        if filename:
            output_dir = tmp_path / Path(filename).stem
        else:
            output_dir = tmp_path / Path(archive_path).stem

        # Remove the output directory if it already exists
        if output_dir.exists():
            shutil.rmtree(output_dir)

        # Uncompress the archive
        subprocess.run(
            ['tar', '-xf', archive_path, '-C', str(tmp_path)],
            check=True
        )

        # If filename is provided, move the extracted content to the output directory
        if filename:
            extracted_content = tmp_path / filename
            if extracted_content.is_file():
                shutil.move(extracted_content, output_dir)
            elif extracted_content.is_dir():
                # If the extracted content is already a directory, rename it to the desired output directory
                shutil.move(extracted_content, output_dir)
            else:
                raise FileNotFoundError(f"The specified filename '{filename}' was not found in the archive.")
        else:
            # If no filename is provided, assume the tarball extracts into a directory with the same stem as the archive
            contents = list(tmp_path.iterdir())
            if len(contents) == 1 and contents[0].is_dir():
                os.rename(contents[0], output_dir)
            else:
                raise ValueError("The archive did not extract into a single directory as expected.")

        # Return the file URL for the repository
        return f"file://{output_dir.resolve()}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to uncompress the archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred while preparing the repository: {e}")

