        # Remove the output directory if it already exists
        if output_dir.exists():
            shutil.rmtree(output_dir)

        # Uncompress the archive
        subprocess.run(
            ['tar', '-xf', archive_path, '-C', str(tmp_path)],
            check=True
        )

        # If filename is provided, move the extracted content to the output directory
        if filename:
            extracted_content = tmp_path / filename
            if extracted_content.is_file():
                shutil.move(extracted_content, output_dir)
            elif extracted_content.is_dir():
                # If the extracted content is already a directory, rename it to the desired output directory
                shutil.move(extracted_content, output_dir)
            else:
                raise FileNotFoundError(f"The specified filename '{filename}' was not found in the archive.")
        else:
            # If no filename is provided, assume the tarball extracts into a directory with the same stem as the archive
            contents = list(tmp_path.iterdir())
            if len(contents) == 1 and contents[0].is_dir():
                os.rename(contents[0], output_dir)
            else:
                raise ValueError("The archive did not extract into a single directory as expected.")

        # Return the file URL for the repository
        return f"file://{output_dir.resolve()}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to uncompress the archive: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred while preparing the repository: {e}")

