    import pickle
    import traceback

    def execute_function():
        try:
            func(*args)
        except Exception as e:
            traceback.print_exc()
            sys.exit(1)

    def target_function():
        if extra_env:
            os.environ.update(extra_env)
        execute_function()

    with open(os.devnull, 'w') as devnull:
        try:
