def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
        except (FileNotFoundError, IOError) as e:
            log_records.append(logging.makeLogRecord({
                'name': 'config_loader',
                'level': logging.ERROR,
                'msg': f'File not found or could not be read: {filename}',
                'exc_info': e
            }))
            continue
        except json.JSONDecodeError as e:
            log_records.append(logging.makeLogRecord({
                'name': 'config_loader',
                'level': logging.ERROR,
                'msg': f'Failed to parse JSON in file: {filename}',
                'exc_info': e
            }))
            continue

        if resolve_env:
            config = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config.items()}

        config_dict[filename] = {**config, **overrides.get(filename, {})}

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import configparser
    import os

    config_dict = {}
    error_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        if not os.path.isfile(filename):
            error_records.append(logging.LogRecord(
                name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                msg=f"Configuration file not found: {filename}", args=(), exc_info=None))
            continue

        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as config_file:
                config.read_file(config_file)

            # Apply environment variable resolution if requested
            if resolve_env:
                for section in config.sections():
                    for key, value in config.items(section):
                        if value.startswith('$') and value[1:] in os.environ:
                            config.set(section, key, os.environ[value[1:]])

            # Apply overrides
            for section, options in overrides.get(filename, {}).items():
                for key, value in options.items():
                    if section in config:
                        config.set(section, key, value)
                    else:
                        config.add_section(section)
                        config.set(section, key, value)

            config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}

        except Exception as e:
            error_records.append(logging.LogRecord(
                name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                msg=f"Error parsing configuration file: {filename}", args=(str(e),), exc_info=None))

    return config_dict, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import logging
    from configparser import ConfigParser, ParsingError

    if overrides is None:
        overrides = {}

    configs = {}
    log_records = []

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"Configuration file {filename} not found.")

            parser = ConfigParser()
            parser.read(filename)

            if resolve_env:
                for section in parser.sections():
                    for key, value in parser.items(section):
